// Simple Asteroid Dodge game
// Canvas with id="game" must exist in the HTML
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return console.error('Canvas #game not found');
  const ctx = canvas.getContext('2d');
  const W = canvas.width = canvas.clientWidth || 800;
  const H = canvas.height = canvas.clientHeight || 600;

  // ----- Player -----
  const player = {
    w: 40,
    h: 20,
    x: W / 2 - 20,
    y: H - 30,
    speed: 5,
    color: '#0f0',
    cooldown: 0
  };

  // ----- Game state -----
  const asteroids = [];
  const lasers = [];
  let score = 0;
  let gameOver = false;

  // ----- Input handling -----
  const keys = {};
  window.addEventListener('keydown', e => { keys[e.code] = true; });
  window.addEventListener('keyup', e => { keys[e.code] = false; });

  // ----- Helper functions -----
  function spawnAsteroid() {
    const size = Math.random() * 30 + 20;
    asteroids.push({
      x: Math.random() * (W - size),
      y: -size,
      w: size,
      h: size,
      speed: 1 + Math.random() * 2 + score * 0.001
    });
  }

  function update() {
    if (gameOver) return;
    // Player movement
    if (keys['ArrowLeft']) player.x -= player.speed;
    if (keys['ArrowRight']) player.x += player.speed;
    player.x = Math.max(0, Math.min(W - player.w, player.x));

    // Shooting
    if (keys['Space'] && player.cooldown <= 0) {
      lasers.push({ x: player.x + player.w / 2 - 2, y: player.y, w: 4, h: 10, speed: 7 });
      player.cooldown = 15; // frames
    }
    if (player.cooldown > 0) player.cooldown--;

    // Update lasers
    for (let i = lasers.length - 1; i >= 0; i--) {
      const l = lasers[i];
      l.y -= l.speed;
      if (l.y + l.h < 0) lasers.splice(i, 1);
    }

    // Spawn asteroids periodically
    if (Math.random() < 0.02) spawnAsteroid();

    // Update asteroids
    for (let i = asteroids.length - 1; i >= 0; i--) {
      const a = asteroids[i];
      a.y += a.speed;
      // collision with player
      if (a.x < player.x + player.w && a.x + a.w > player.x && a.y + a.h > player.y) {
        gameOver = true;
      }
      // collision with lasers
      for (let j = lasers.length - 1; j >= 0; j--) {
        const l = lasers[j];
        if (l.x < a.x + a.w && l.x + l.w > a.x && l.y < a.y + a.h && l.y + l.h > a.y) {
          lasers.splice(j, 1);
          asteroids.splice(i, 1);
          score++;
          break;
        }
      }
      // asteroid passes bottom
      if (a.y > H) {
        asteroids.splice(i, 1);
        // could reduce score or ignore; treat as missed
      }
    }
  }

  function draw() {
    ctx.clearRect(0, 0, W, H);
    // Player
    ctx.fillStyle = player.color;
    ctx.fillRect(player.x, player.y, player.w, player.h);
    // Lasers
    ctx.fillStyle = '#ff0';
    lasers.forEach(l => ctx.fillRect(l.x, l.y, l.w, l.h));
    // Asteroids
    ctx.fillStyle = '#f55';
    asteroids.forEach(a => ctx.fillRect(a.x, a.y, a.w, a.h));
    // Score
    ctx.fillStyle = '#fff';
    ctx.font = '16px sans-serif';
    ctx.fillText('Score: ' + score, 10, 20);
    // Game over text
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.fillRect(0, 0, W, H);
      ctx.fillStyle = '#fff';
      ctx.font = '48px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', W / 2, H / 2);
    }
  }

  function loop() {
    if (!gameOver) update();
    draw();
    requestAnimationFrame(loop);
  }

  // start the game
  loop();
})();
